CREATE OR REPLACE FUNCTION public.create_incident_join_code(p_incident_id uuid, p_minutes integer DEFAULT 10080)
 RETURNS TABLE(code text, expires_at timestamp with time zone, join_code_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_code text;v_id uuid;v_exp timestamptz;i integer:=0;
begin
 if auth.uid() is null or not (public.firemap_is_sk() or exists(select 1 from public.incidents x join public.firemap_accounts a on a.user_id=x.sztab_id where x.id=p_incident_id and a.user_id=auth.uid() and a.enabled and a.role='SZTAB')) then raise exception 'Brak dostępu do tego zdarzenia';end if;
 if not exists(select 1 from public.incidents x where x.id=p_incident_id and x.active) then raise exception 'Zdarzenie nie jest aktywne';end if;
 p_minutes:=greatest(10,least(coalesce(p_minutes,10080),10080));v_exp:=now()+make_interval(mins=>p_minutes);
 -- Serialize allocation in the six-digit namespace, including concurrent requests.
 perform pg_advisory_xact_lock(71420391);
 loop
  i:=i+1;
  v_code:=lpad(((('x'||encode(extensions.gen_random_bytes(4),'hex'))::bit(32)::bigint % 1000000))::text,6,'0');
  exit when not exists(select 1 from public.incident_join_codes c where c.code=v_code and c.active and c.expires_at>now());
  if i>50 then raise exception 'Nie udało się wygenerować kodu';end if;
 end loop;
 insert into public.incident_join_codes(incident_id,code,expires_at,created_by) values(p_incident_id,v_code,v_exp,auth.uid()) returning id into v_id;
 return query select v_code,v_exp,v_id;
end $function$
CREATE OR REPLACE FUNCTION public.deactivate_incident_join_code(p_join_code_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not (public.firemap_is_sk() or exists(select 1 from public.incident_join_codes c join public.incidents i on i.id=c.incident_id join public.firemap_accounts a on a.user_id=i.sztab_id where c.id=p_join_code_id and a.user_id=auth.uid() and a.role='SZTAB' and a.enabled)) then raise exception 'Brak dostępu do tego kodu';end if;
 update public.incident_join_codes set active=false where id=p_join_code_id;
 return found;
end $function$
CREATE OR REPLACE FUNCTION public.expire_external_force_sessions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare n integer;begin
 if not public.firemap_is_sk() then raise exception 'Brak uprawnień SK';end if;
 update public.incident_join_codes set active=false where active and expires_at<=now();
 with expired as (
   update public.external_force_sessions s set active=false
   where s.active and (s.expires_at<=now() or not exists(select 1 from public.incidents i where i.id=s.incident_id and coalesce(i.active,true)=true))
   returning s.vehicle_id
 )
 update public.vehicles v set status='BASE',updated_at=now() where v.id in(select vehicle_id from expired);
 get diagnostics n=row_count;return n;
end;$function$
CREATE OR REPLACE FUNCTION public.external_force_join(p_code text, p_force_group text, p_specialist_group text, p_voivodeship text, p_county text, p_unit text, p_call_sign text, p_vehicle_type text)
 RETURNS TABLE(session_token text, session_id uuid, vehicle_id uuid, incident_id uuid, expires_at timestamp with time zone, incident_kind text, incident_description text, incident_lat double precision, incident_lng double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare c public.incident_join_codes%rowtype;s_token text;s_id uuid;v_id uuid;s_exp timestamptz;inc public.incidents%rowtype;
begin
 p_code:=regexp_replace(coalesce(p_code,''),'\s','','g');
 if p_force_group not in ('WOO','COO','EXTERNAL') then raise exception 'Nieprawidłowa grupa sił';end if;
 if p_specialist_group is not null and p_specialist_group<>'' and p_specialist_group not in ('CHEM_ECO','WATER_DIVE','HEIGHT','TECH_SEARCH','USAR','DRONE','OTHER') then raise exception 'Nieprawidłowa grupa specjalistyczna';end if;
 if p_vehicle_type not in ('GBA','GCBA','GBM','GLM','SD','SLRt','SLOp','SLKw','SLRR','MIKROBUS','PRZYCZEPA','QUAD','INNY') then raise exception 'Nieprawidłowy typ pojazdu';end if;
 if length(trim(coalesce(p_voivodeship,'')))<2 or length(trim(coalesce(p_county,'')))<2 or length(trim(coalesce(p_unit,'')))<2 or length(trim(coalesce(p_call_sign,'')))<1 then raise exception 'Uzupełnij dane zastępu';end if;
 select jc.* into c from public.incident_join_codes jc where jc.code=p_code and jc.active=true and jc.expires_at>now() order by jc.created_at desc limit 1;
 if c.id is null then raise exception 'Kod jest nieprawidłowy lub wygasł';end if;
 select i.* into inc from public.incidents i where i.id=c.incident_id and coalesce(i.active,true)=true;
 if inc.id is null then raise exception 'Zdarzenie zostało zakończone';end if;
 s_token:=encode(extensions.gen_random_bytes(24),'hex');s_exp:=c.expires_at;
 insert into public.external_force_sessions as efs(incident_id,join_code_id,token_hash,force_group,specialist_group,origin_voivodeship,origin_county,origin_unit,call_sign,vehicle_type,expires_at)
 values(c.incident_id,c.id,extensions.digest(s_token,'sha256'),p_force_group,nullif(p_specialist_group,''),trim(p_voivodeship),trim(p_county),trim(p_unit),trim(p_call_sign),trim(p_vehicle_type),s_exp)
 returning efs.id,efs.vehicle_id into s_id,v_id;
 return query select s_token,s_id,v_id,c.incident_id,s_exp,inc.kind::text,coalesce(inc.description,''),inc.lat::double precision,inc.lng::double precision;
end;$function$
CREATE OR REPLACE FUNCTION public.external_force_leave(p_session_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$ declare s public.external_force_sessions%rowtype;begin
 select * into s from public.external_force_sessions where token_hash=extensions.digest(coalesce(p_session_token,''),'sha256') and active=true limit 1;
 if s.id is null then return false;end if;
 update public.external_force_sessions set active=false,last_seen_at=now() where id=s.id;
 update public.vehicles set status='BASE',updated_at=now() where id=s.vehicle_id;
 return true;
end;$function$
CREATE OR REPLACE FUNCTION public.external_force_peers(p_session_token text)
 RETURNS TABLE(id uuid, call_sign text, unit_name text, vehicle_type text, status text, lat double precision, lng double precision, updated_at timestamp with time zone, force_group text, specialist_group text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.external_force_sessions%rowtype;
begin
 if p_session_token is null or length(p_session_token)<>48 then
  raise exception 'Sesja wygasła';
 end if;
 select e.* into s from public.external_force_sessions e
 where e.token_hash=extensions.digest(p_session_token,'sha256') and e.active and e.expires_at>now();
 if s.id is null or not exists(select 1 from public.incidents i where i.id=s.incident_id and i.active) then
  raise exception 'Sesja wygasła';
 end if;
 return query
 select v.id,v.call_sign,v.unit_name,v.vehicle_type,v.status,v.lat,v.lng,v.updated_at,v.force_group,v.specialist_group
 from public.vehicles v
 where v.incident_id=s.incident_id and v.id<>s.vehicle_id and v.status<>'BASE'
 and v.lat between -90 and 90 and v.lng between -180 and 180
 and (v.external_session_id is null or exists(
  select 1 from public.external_force_sessions peer
  where peer.id=v.external_session_id and peer.vehicle_id=v.id and peer.incident_id=s.incident_id
  and peer.active and peer.expires_at>now()
 ))
 order by v.id;
end;
$function$
CREATE OR REPLACE FUNCTION public.external_force_update(p_session_token text, p_lat double precision, p_lng double precision, p_status text, p_accuracy double precision DEFAULT NULL::double precision, p_speed double precision DEFAULT NULL::double precision, p_heading double precision DEFAULT NULL::double precision)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare s public.external_force_sessions%rowtype;
begin
 if p_status not in ('DISPATCHED','ON_SCENE','RETURNING','BASE') then raise exception 'Nieprawidłowy status';end if;
 if p_lat<-90 or p_lat>90 or p_lng<-180 or p_lng>180 then raise exception 'Nieprawidłowa pozycja';end if;
 select * into s from public.external_force_sessions where token_hash=extensions.digest(coalesce(p_session_token,''),'sha256') and active=true and expires_at>now() limit 1;
 if s.id is null then raise exception 'Sesja wygasła';end if;
 if not exists(select 1 from public.incidents i where i.id=s.incident_id and coalesce(i.active,true)=true) then
   update public.external_force_sessions set active=false where id=s.id;
   update public.vehicles set status='BASE',updated_at=now() where id=s.vehicle_id;
   raise exception 'Zdarzenie zostało zakończone';
 end if;
 update public.external_force_sessions set last_seen_at=now() where id=s.id;
 insert into public.vehicles(id,unit_name,call_sign,vehicle_type,status,lat,lng,accuracy,speed,heading,updated_at,incident_id,force_group,specialist_group,origin_voivodeship,origin_county,origin_unit,external_session_id)
 values(s.vehicle_id,s.origin_unit,s.call_sign,s.vehicle_type,p_status,p_lat,p_lng,case when p_accuracy is null then null else round(p_accuracy)::integer end,p_speed,p_heading,now(),s.incident_id,s.force_group,s.specialist_group,s.origin_voivodeship,s.origin_county,s.origin_unit,s.id)
 on conflict(id) do update set unit_name=excluded.unit_name,call_sign=excluded.call_sign,vehicle_type=excluded.vehicle_type,status=excluded.status,lat=excluded.lat,lng=excluded.lng,accuracy=excluded.accuracy,speed=excluded.speed,heading=excluded.heading,updated_at=excluded.updated_at,incident_id=excluded.incident_id,force_group=excluded.force_group,specialist_group=excluded.specialist_group,origin_voivodeship=excluded.origin_voivodeship,origin_county=excluded.origin_county,origin_unit=excluded.origin_unit,external_session_id=excluded.external_session_id;
 return true;
end;$function$
CREATE OR REPLACE FUNCTION public.firemap_cleanup_closed_incident_drawings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.active is true and new.active is false then
    delete from public.incident_drawings where incident_id=new.id;
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.firemap_close_external_sessions_on_incident()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
 if old.active is distinct from new.active and new.active=false then
   update public.incident_join_codes set active=false where incident_id=new.id;
   update public.external_force_sessions set active=false where incident_id=new.id and active=true;
   update public.vehicles set status='BASE',updated_at=now() where external_session_id in(select id from public.external_force_sessions where incident_id=new.id);
 end if;
 return new;
end;$function$
CREATE OR REPLACE FUNCTION public.firemap_is_sk()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists(select 1 from public.firemap_accounts a where a.user_id=auth.uid() and a.enabled and a.role='SK'); $function$
CREATE OR REPLACE FUNCTION public.firemap_sztab_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 select user_id from public.firemap_accounts where user_id=auth.uid() and enabled and role='SZTAB'
$function$
